function formatContinental(n) {
  const x = Number(n);
  if (!Number.isFinite(x)) return String(n);
  const sign = x < 0 ? "-" : "";
  const a = Math.abs(x);
  const parts = a.toFixed(2).split(".");
  const grouped = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return sign + grouped + "," + parts[1];
}
function formatAu(n) {
  const x = Number(n);
  if (!Number.isFinite(x)) return "—";
  const sign = x < 0 ? "-" : "";
  const a = Math.abs(x);
  if (a >= 1e6) return sign + formatContinental(a / 1e6) + " million €Au";
  return sign + formatContinental(a) + " €Au";
}
async function loadJson(url) {
  const r = await fetch(url, { cf: { cacheTtl: 120, cacheEverything: true } });
  if (!r.ok) throw new Error(url + " " + r.status);
  return r.json();
}
function stocksPage(pack) {
  const release = ((pack.release || {}).esef || []).map(r => r.dataset + ": " + r.window + " (history from " + r.history_from + ")").join(" · ");
  const rowsSrc = (pack.ranked_latest && pack.ranked_latest.length) ? pack.ranked_latest : (pack.observations || []);
  const rows = rowsSrc.map(o => {
    const label = o.name || o.lei;
    const href = o.lei_url || ("https://search.gleif.org/#/record/" + o.lei);
    return `<tr>
      <td>${o.geo || ""}</td>
      <td><a href="${href}">${label}</a><div class="machine">${o.lei}</div></td>
      <td>${o.period || ""}</td>
      <td class="num">${o.equity_au != null ? formatAu(o.equity_au) : "—"}</td>
      <td class="num">${o.assets_au != null ? formatAu(o.assets_au) : "—"}</td>
      <td class="num">${o.revenue_au != null ? formatAu(o.revenue_au) : "—"}</td>
      <td class="num">${o.profit_au != null ? formatAu(o.profit_au) : "—"}</td>
    </tr>`;
  }).join("");
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"/><title>European stocks in €Au</title>
<link rel="stylesheet" href="/aurum-euro/static/styles.css"/></head><body>
<header><div class="mark">Aurum Euro · €Au</div>
<nav><a href="/aurum-euro">€Au accounts</a><a href="/aurum-euro/stocks">European stocks</a></nav></header>
<main>
<h1>European listed issuers in Aurum Euro</h1>
<p class="notice">${SCALE_RULE}</p>
<p class="lead">Ranked by equity in €Au, highest first. The name is the legal entity; the LEI remains the identifier. Historical filings stay in the machine file.</p>
<p class="notice">Release window: ${release || "ESEF within four months of year-end. History kept."} · generated ${pack.generated_at || "—"}</p>
<div class="table-wrap"><table>
<thead><tr><th>State</th><th>Entity</th><th>Period</th><th>Equity (€Au)</th><th>Assets (€Au)</th><th>Revenue (€Au)</th><th>Profit (€Au)</th></tr></thead>
<tbody>${rows || "<tr><td colspan=7>Snapshot not yet available.</td></tr>"}</tbody></table></div>
</main></body></html>`;
}
async function aurumEuro(request, url, path) {
  const cors = { "Access-Control-Allow-Origin": "*" };
  if (path === "/aurum-euro" || path === "/aurum-euro/") return new Response(AURUM_HTML, { headers: { "Content-Type": "text/html; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/static/styles.css") return new Response(AURUM_CSS, { headers: { "Content-Type": "text/css; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/static/app.js") return new Response(AURUM_JS, { headers: { "Content-Type": "application/javascript; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/static/methodology.html") return new Response(AURUM_METH, { headers: { "Content-Type": "text/html; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/static/provenance.html") return new Response(AURUM_PROV, { headers: { "Content-Type": "text/html; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/static/sources.html") return new Response(AURUM_SOURCES, { headers: { "Content-Type": "text/html; charset=utf-8", ...cors } });
  let accounts = null, stocks = null;
  try {
    if (path === "/aurum-euro/snapshot.json" || path.startsWith("/aurum-euro/api/v1/")) accounts = await loadJson(ACCOUNTS_URL);
  } catch (e) { accounts = { error: String(e) }; }
  try {
    if (path === "/aurum-euro/stocks" || path.startsWith("/aurum-euro/api/v1/stocks") || path === "/aurum-euro/api/v1/health")
      stocks = await loadJson(STOCKS_URL);
  } catch (e) { stocks = { error: String(e) }; }
  if (path === "/aurum-euro/stocks" || path === "/aurum-euro/stocks/") return new Response(stocksPage(stocks || {}), { headers: { "Content-Type": "text/html; charset=utf-8", ...cors } });
  if (path === "/aurum-euro/snapshot.json") return Response.json(accounts || {}, { headers: cors });
  if (path === "/aurum-euro/api/v1/stocks/issuers") return Response.json(stocks || {}, { headers: cors });
  if (path === "/aurum-euro/api/v1/stocks/venues") return Response.json(AURUM_VENUES, { headers: cors });
  if (path === "/aurum-euro/api/v1/definition") return Response.json({ ...(accounts && accounts.definition || {}), publication: "€Au per inhabitant" }, { headers: cors });
  if (path === "/aurum-euro/api/v1/gold") return Response.json({ unit: "euro per troy ounce of gold (input to €Au)", rows: accounts && accounts.gold }, { headers: cors });
  if (path === "/aurum-euro/api/v1/datasets" || path === "/aurum-euro/api/v1/catalog")
    return Response.json({ publication_unit: "€Au per inhabitant", catalog: accounts && accounts.catalog, series: accounts && accounts.series, release: accounts && accounts.release });
  if (path === "/aurum-euro/api/v1/health" || path === "/aurum-euro/api/v1/status") {
    return Response.json({
      status: "ok", service: "aurum-euro", publication_unit: "€Au per inhabitant",
      sort: "€Au descending",
      stocks_named: stocks && stocks.names_resolved,
      stocks_ranked: stocks && (stocks.ranked_latest || []).length,
      release: stocks && stocks.release,
      automation: "github-action aurum-euro-refresh"
    }, { headers: cors });
  }
  return new Response(JSON.stringify({ error: "Not found", path }), { status: 404, headers: { "Content-Type": "application/json", ...cors } });
}

